const test = require('node:test');
const assert = require('node:assert');
const { parseDuration, formatDuration } = require('../src/duration.js');

test('parseDuration handles each shape', () => {
  assert.strictEqual(parseDuration('1h30m'), 5400);
  assert.strictEqual(parseDuration('90s'), 90);
  assert.strictEqual(parseDuration('2h'), 7200);
  assert.strictEqual(parseDuration('45m'), 2700);
  assert.strictEqual(parseDuration('2h5s'), 7205);
});

test('parseDuration rejects invalid input', () => {
  assert.strictEqual(parseDuration(''), null);
  assert.strictEqual(parseDuration('h30m'), null);
  assert.strictEqual(parseDuration('30m2h'), null);
  assert.strictEqual(parseDuration('90'), null);
});

test('formatDuration emits shortest form', () => {
  assert.strictEqual(formatDuration(5400), '1h30m');
  assert.strictEqual(formatDuration(90), '1m30s');
  assert.strictEqual(formatDuration(0), '0s');
  assert.strictEqual(formatDuration(3661), '1h1m1s');
  assert.strictEqual(formatDuration(7200), '2h');
});

