'use strict';

function parseDuration(str) {
  if (typeof str !== 'string') { return null; }
  var m = /^(?:(\d+)h)?(?:(\d+)m)?(?:(\d+)s)?$/.exec(str);
  if (!m || (!m[1] && !m[2] && !m[3])) { return null; }
  var h = m[1] ? parseInt(m[1], 10) : 0;
  var min = m[2] ? parseInt(m[2], 10) : 0;
  var s = m[3] ? parseInt(m[3], 10) : 0;
  return h * 3600 + min * 60 + s;
}

function formatDuration(totalSeconds) {
  if (totalSeconds === 0) { return '0s'; }
  var h = Math.floor(totalSeconds / 3600);
  var rem = totalSeconds % 3600;
  var min = Math.floor(rem / 60);
  var s = rem % 60;
  var out = '';
  if (h) { out += h + 'h'; }
  if (min) { out += min + 'm'; }
  if (s) { out += s + 's'; }
  return out;
}

module.exports = { parseDuration: parseDuration, formatDuration: formatDuration };
